        varCurrentFID: gblRecordSelectedProject.'Final Investment Decision',
        varCurrentYear: Year(dtp_Milestones_DisplayProject_Body_General_Content_FiD.SelectedDate),
        varPreviousYear: Year(dtp_Milestones_DisplayProject_Body_General_Content_FiD.SelectedDate) - 1
    },
    With(
        {
            varRecordEstimationPriceInflationDirect: LookUp(
                'Estimation Price Inflations',
                'FID Year' = varCurrentYear
            ),
            varRecordEstimationPriceInflationDirectPrevious: LookUp(
                'Estimation Price Inflations',
                'FID Year' = varPreviousYear
            )
        },
        ClearCollect(
            colLogs,
            $"Plant Cost will be recalculated. {Char(10)}Previous FID: {Text(
                varCurrentFID,
                "dd.mm.yyyy"
            )}, New FID: {Text(
                varSelectedFID,
                "dd.mm.yyyy"
            )}"
        );
        If(
            varSelectedFID <> varCurrentFID,
            With(
                {
                    varAnnualPriceEscalationIndex: varRecordEstimationPriceInflationDirect.'Annual Price Escalation Index',
                    varAccumulatedPriceEscalationIndex: varRecordEstimationPriceInflationDirect.'Accumulated Price Escalation Index',
                    varAccumulatedPriceEscalationIndexPrevious: varRecordEstimationPriceInflationDirectPrevious.'Accumulated Price Escalation Index',
                    varAccumulatedIndex: (varRecordEstimationPriceInflationDirectPrevious.'Accumulated Price Escalation Index' + (varRecordEstimationPriceInflationDirect.'Accumulated Price Escalation Index' - varRecordEstimationPriceInflationDirectPrevious.'Accumulated Price Escalation Index') * Month(varSelectedFID) / 12)
                },
                Collect(
                    colLogs,
                    $"Previous Year: {varPreviousYear}; Month Index {Month(varSelectedFID) / 12}; {Char(10)}Annual Price Escalation Index: {varAnnualPriceEscalationIndex}; {Char(10)}Accumulated Price Escalation Index: {varAccumulatedPriceEscalationIndex}; {Char(10)}Accumulated Price Escalation Index Previous: {varAccumulatedPriceEscalationIndexPrevious}; {Char(10)}Price Index: {varAccumulatedIndex}",
                    $"Formula: ({varAccumulatedPriceEscalationIndexPrevious} + ({varRecordEstimationPriceInflationDirect.'Accumulated Price Escalation Index'} - {varRecordEstimationPriceInflationDirectPrevious.'Accumulated Price Escalation Index'}) * {Month(varSelectedFID) / 12}) {Char(10)}"
                );
                ForAll(
                    colProjectGeneratorsTemporary As source,
                    With(
                        {
                            varRecordGenerator: source.Generator,
                            varAdditionalCost: Text(source.Generator.'Additional foundation cost'),
                            varFoundationCostIncluded: Text(source.Generator.'Foundation cost included'),
                            varGeneratorCostsPerWtgNet: Switch(
                                Value(source.'Number of Generators'),
                                1,
                                source.Generator.'1 WTG price',
                                2,
                                source.Generator.'2 WTG price',
                                3,
                                source.Generator.'3 WTG price',
                                4,
                                source.Generator.'4 WTG price',
                                source.Generator.'5 WTG price'
                            ),
                            varGeneratorsNumber: Value(source.'Number of Generators')
                        },
                        With(
                            {
                                varGeneratorCostsPerWtg: If(
                                    varFoundationCostIncluded = "Yes",
                                    Switch(
                                        varGeneratorsNumber,
                                        1,
                                        varGeneratorCostsPerWtgNet * varAccumulatedIndex,
                                        2,
                                        varGeneratorCostsPerWtgNet * varAccumulatedIndex,
                                        3,
                                        varGeneratorCostsPerWtgNet * varAccumulatedIndex,
                                        4,
                                        varGeneratorCostsPerWtgNet * varAccumulatedIndex,
                                        varGeneratorCostsPerWtgNet * varAccumulatedIndex
                                    ),
                                    Switch(
                                        Value(varGeneratorsNumber),
                                        1,
                                        (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedIndex,
                                        2,
                                        (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedIndex,
                                        3,
                                        (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedIndex,
                                        4,
                                        (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedIndex,
                                        (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedIndex
                                    )
                                )
                            },
                            Collect(
                                colLogs,
                                $"Formula ({varGeneratorsNumber}-WTG's): ({varGeneratorCostsPerWtg} * {varGeneratorsNumber})"
                            );
                            Patch(
                                colProjectGenerators,
                                LookUp(
                                    colProjectGenerators,
                                    GeneratorTypeInProject = source.GeneratorTypeInProject
                                ),
                                {'Generators Cost': varGeneratorsNumber * varGeneratorCostsPerWtg}
                            );
                        )
                    )
                )
                // ForAll end
            );
        )
    )
